// Indexer properties. Array of colored squares 
uses GraphABC;

const 
  sz = 50;
  dim = 10;
  delay = 500;

type 
  /// 
  VisualArray = class
  private
    a: array of Color;
    procedure SetItem(i: integer; x: Color); // Procedure setting color of i-th square
    begin
      if (i<0) or (i>=a.Length) then
        raise new System.ArgumentException('Index out of bounds: '+IntToStr(i));
      a[i] := x;
      Draw(i);
    end;
    function GetItem(i: integer): Color; // Function returning color of i-th square
    begin
      if (i<0) or (i>=a.Length) then
        raise new System.ArgumentException('Index out of bounds: '+IntToStr(i));
      Result := a[i];
    end;
  public
    constructor (n: integer);
    begin
      a := ArrFill(n,Color.White);
      Draw;
    end;
    /// Draws i-th square
    procedure Draw(i: integer);
    begin
      Brush.Color := a[i];
      Rectangle(sz+sz*i,sz,sz+sz*(i+1)+1,sz+sz);
    end;
    /// Draws array of colored squares
    procedure Draw;
    begin
      for var i:=0 to a.Length-1 do
        Draw(i);
    end;
    /// Default indexer property
    property Item[i: integer]: Color read GetItem write SetItem; default;
  end;

