type Node<T> = auto class
  data: T;
  left,right: Node<T>;
end;

function CNode<T>(x: T; l: Node<T> := nil; 
  r: Node<T> := nil): Node<T> := new Node<T>(x,l,r);

function Infix<T>(root: Node<T>): sequence of T;
begin
  if root = nil then exit;
  yield sequence Infix(root.left);
  yield root.data;
  yield sequence Infix(root.right);
end;

begin
  var root := CNode(1,CNode(2,CNode(3),CNode(4)),CNode(5));
  Infix(root).Print;
end.

// Inheritance. Polymorphism and virtual functions
type 
  Person = class
  private
    name: string;
    age: integer;
  public
    constructor (n: string; a: integer);
    begin
      name := n; age := a;
    end;
    procedure Print; virtual; // Virtual function. Overridden in derived classes
    begin
      var s := GetType.ToString;
      write('Type: ',Copy(s,pos('.',s)+1,Length(s)):7,'   Name: ',name,'   Age: ',age);
    end;
    procedure Println;
    begin
      Print;
      writeln;
    end;
  end;

  Pupil = class(Person) // Pupil - inheritor of Person
  private
    clas: integer;
  public
    constructor (n: string; a,c: integer);
    begin
      inherited Create(n,a); // Call inherited constructor
      clas := c;
    end;
    procedure Print; override;
    begin
      inherited Print;
      write('   Class: ',clas);
    end;
  end;

  Teacher = class(Person)
  private
    predm: string;
  public
    constructor (n: string; a: integer; p: string);
    begin
      inherited Create(n,a); // Call inherited constructor
      predm := p;
    end;
    procedure Print; override;
    begin
      inherited Print;
      write('   Subject: ',predm);
    end;
  end;

